import * as http from 'node:http';
import * as zlib from 'node:zlib';
function main(): void {
  const original = 'chunked gzip body line\n'.repeat(50);
  const gz: Buffer = zlib.gzipSync(Buffer.from(original));
  const srv = http.createServer((req: any, res: any) => {
    res.writeHead(200, { 'content-type': 'application/gzip' });
    const step = Math.ceil(gz.length / 4);
    for (let i = 0; i < gz.length; i += step) res.write(gz.subarray(i, i + step));
    res.end();
  });
  srv.listen(0, '127.0.0.1', (): void => {
    const port = (srv.address() as any).port;
    http.get({ host: '127.0.0.1', port, path: '/' }, (res: any): void => {
      const chunks: Buffer[] = [];
      res.on('data', (chunk: Buffer): void => { chunks.push(chunk); });
      res.on('end', (): void => {
        const text = zlib.gunzipSync(Buffer.concat(chunks)).toString('utf8');
        console.log(res.statusCode, text.split('\n').length, text.slice(0, 22), text === original);
        srv.close();
      });
    });
  });
}
